using EquipmentBorrowing.Application.Interfaces;
using EquipmentBorrowing.Application.Queries;
using EquipmentBorrowing.Application.Results;
using EquipmentBorrowing.Application.Services;
using EquipmentBorrowing.Domain;

namespace EquipmentBorrowing.Api;

internal static class ApiRoutes
{
    private static string Key(int id) => id.ToString(System.Globalization.CultureInfo.InvariantCulture);
    private static IResult Error(int status, string code, string message) => Results.Json(new { code, message }, statusCode: status);
    private static int? ParseId(string id) => int.TryParse(id, out var value) && value > 0 ? value : null;
    private static object StudentDto(Student s) => new { id = Key(s.Id), studentNumber = s.StudentNumber, fullName = s.Name, contact = s.ContactInfo, isEligible = s.IsAllowedToBorrow };
    private static object EquipmentDto(Equipment e) => new { id = Key(e.Id), equipmentCode = e.Identifier, name = e.Name, description = e.Description, isAvailable = e.IsAvailable };
    private static object BorrowDto(BorrowingRecord b) => new { id = Key(b.BorrowingId), studentId = Key(b.StudentId), equipmentId = Key(b.EquipmentId), borrowedDate = b.DateBorrowed.ToString("yyyy-MM-dd"), expectedReturnDate = b.ExpectedReturnDate.ToString("yyyy-MM-dd"), returnedDate = b.ActualReturnDate?.ToString("yyyy-MM-dd"), status = b.Status.ToString(), studentNumber = b.StudentNumber, studentName = b.StudentName, equipmentCode = b.EquipmentIdentifier, equipmentName = b.EquipmentName };

    public static void MapStudentApi(this WebApplication app)
    {
        var g = app.MapGroup("/api/v1/students");
        g.MapGet("", async (string? search, IStudentRepository repo, CancellationToken ct) =>
        {
            var q = await repo.GetAllAsync(ct); if (search is not null) { var t = search.Trim(); if (t.Length == 0) return Error(400,"invalid_query","Search cannot be blank."); q = q.Where(s => s.Name.Contains(t,StringComparison.OrdinalIgnoreCase) || s.StudentNumber.Contains(t,StringComparison.OrdinalIgnoreCase)).ToArray(); }
            return Results.Ok(q.Select(StudentDto));
        });
        g.MapGet("/{id}", async (string id, IStudentRepository repo, CancellationToken ct) => { var n=ParseId(id); if(n is null)return Error(404,"not_found","Student was not found."); var s=await repo.GetByIdAsync(n.Value,ct); return s is null?Error(404,"not_found","Student was not found."):Results.Ok(StudentDto(s)); });
        g.MapPost("", async (StudentInput x, StudentManagementService service, IStudentRepository repo, CancellationToken ct) =>
        { if(string.IsNullOrWhiteSpace(x.StudentNumber)||string.IsNullOrWhiteSpace(x.FullName))return Error(400,"invalid_request","Student number and full name are required."); var r=await service.RegisterStudentAsync(x.StudentNumber,x.FullName,x.Contact, cancellationToken:ct); if(!r.IsSuccess) return r.ErrorMessage?.Contains("already exists",StringComparison.OrdinalIgnoreCase)==true?Error(409,"duplicate_student",r.ErrorMessage):Error(400,"invalid_request",r.ErrorMessage??"Invalid student."); var s=await repo.GetByStudentNumberAsync(x.StudentNumber,ct); return s is null?Error(500,"server_error","The saved student could not be read."):Results.Created($"/api/v1/students/{Key(s.Id)}",StudentDto(s)); });
        g.MapPut("/{id}", async (string id, StudentInput x, StudentManagementService service, IStudentRepository repo, CancellationToken ct) =>
        { var n=ParseId(id); if(n is null)return Error(404,"not_found","Student was not found."); if(string.IsNullOrWhiteSpace(x.StudentNumber)||string.IsNullOrWhiteSpace(x.FullName))return Error(400,"invalid_request","Student number and full name are required."); var current=await repo.GetByIdAsync(n.Value,ct); if(current is null)return Error(404,"not_found","Student was not found."); var r=await service.UpdateStudentAsync(n.Value,x.StudentNumber,x.FullName,x.Contact,current.IsAllowedToBorrow,ct); if(!r.IsSuccess)return r.ErrorMessage?.Contains("not found",StringComparison.OrdinalIgnoreCase)==true?Error(404,"not_found",r.ErrorMessage):r.ErrorMessage?.Contains("already",StringComparison.OrdinalIgnoreCase)==true?Error(409,"duplicate_student",r.ErrorMessage):Error(400,"invalid_request",r.ErrorMessage??"Invalid student."); return Results.Ok(StudentDto((await repo.GetByIdAsync(n.Value,ct))!)); });
        g.MapPatch("/{id}/eligibility", async (string id, EligibilityInput x, IStudentRepository repo, CancellationToken ct) => { var n=ParseId(id); if(n is null)return Error(404,"not_found","Student was not found."); var s=await repo.GetByIdAsync(n.Value,ct); if(s is null)return Error(404,"not_found","Student was not found."); s.SetEligibility(x.IsEligible); await repo.UpdateAsync(s,ct); return Results.Ok(StudentDto((await repo.GetByIdAsync(n.Value,ct))!)); });
        g.MapGet("/{id}/borrowings", async (string id, IStudentRepository students, IBorrowingRepository borrows, IEquipmentRepository equipment, CancellationToken ct) => { var n=ParseId(id); if(n is null)return Error(404,"not_found","Student was not found."); var s=await students.GetByIdAsync(n.Value,ct); if(s is null)return Error(404,"not_found","Student was not found."); var rows=await borrows.GetByStudentIdAsync(n.Value,ct); var result=new List<object>(); foreach(var b in rows){var e=await equipment.GetByIdAsync(b.EquipmentId,ct); if(e is not null)result.Add(BorrowDto(new BorrowingRecord{BorrowingId=b.Id,StudentId=s.Id,StudentNumber=s.StudentNumber,StudentName=s.Name,EquipmentId=e.Id,EquipmentIdentifier=e.Identifier,EquipmentName=e.Name,DateBorrowed=b.DateBorrowed,ExpectedReturnDate=b.ExpectedReturnDate,ActualReturnDate=b.ActualReturnDate,Status=b.Status}));} return Results.Ok(result); });
    }

    public static void MapEquipmentApi(this WebApplication app)
    {
        var g=app.MapGroup("/api/v1/equipment");
        g.MapGet("",async(string? available,IEquipmentRepository repo,CancellationToken ct)=>{bool? filter=null;if(available is not null){if(!bool.TryParse(available,out var b))return Error(400,"invalid_query","available must be true or false.");filter=b;}var list=await repo.GetAllAsync(ct);return Results.Ok(list.Where(e=>filter is null||e.IsAvailable==filter).Select(EquipmentDto));});
        g.MapGet("/{id}",async(string id,IEquipmentRepository repo,CancellationToken ct)=>{var n=ParseId(id);if(n is null)return Error(404,"not_found","Equipment was not found.");var e=await repo.GetByIdAsync(n.Value,ct);return e is null?Error(404,"not_found","Equipment was not found."):Results.Ok(EquipmentDto(e));});
        g.MapPost("",async(EquipmentInput x,EquipmentManagementService service,IEquipmentRepository repo,CancellationToken ct)=>{if(string.IsNullOrWhiteSpace(x.EquipmentCode)||string.IsNullOrWhiteSpace(x.Name))return Error(400,"invalid_request","Equipment code and name are required.");var r=await service.AddEquipmentAsync(x.EquipmentCode,x.Name,x.Description,ct);if(!r.IsSuccess)return r.ErrorMessage?.Contains("already exists",StringComparison.OrdinalIgnoreCase)==true?Error(409,"duplicate_equipment",r.ErrorMessage):Error(400,"invalid_request",r.ErrorMessage??"Invalid equipment.");var e=await repo.GetByIdentifierAsync(x.EquipmentCode,ct);return e is null?Error(500,"server_error","The saved equipment could not be read."):Results.Created($"/api/v1/equipment/{Key(e.Id)}",EquipmentDto(e));});
        g.MapPut("/{id}",async(string id,EquipmentInput x,EquipmentManagementService service,IEquipmentRepository repo,CancellationToken ct)=>{var n=ParseId(id);if(n is null)return Error(404,"not_found","Equipment was not found.");if(string.IsNullOrWhiteSpace(x.EquipmentCode)||string.IsNullOrWhiteSpace(x.Name))return Error(400,"invalid_request","Equipment code and name are required.");var r=await service.UpdateEquipmentAsync(n.Value,x.EquipmentCode,x.Name,x.Description,ct);if(!r.IsSuccess)return r.ErrorMessage?.Contains("not found",StringComparison.OrdinalIgnoreCase)==true?Error(404,"not_found",r.ErrorMessage):r.ErrorMessage?.Contains("already",StringComparison.OrdinalIgnoreCase)==true?Error(409,"duplicate_equipment",r.ErrorMessage):Error(400,"invalid_request",r.ErrorMessage??"Invalid equipment.");return Results.Ok(EquipmentDto((await repo.GetByIdAsync(n.Value,ct))!));});
        g.MapGet("/{id}/borrowings",async(string id,IEquipmentRepository equipment,BorrowingQueryService query,CancellationToken ct)=>{var n=ParseId(id);if(n is null||await equipment.GetByIdAsync(n.Value,ct) is null)return Error(404,"not_found","Equipment was not found.");return Results.Ok((await query.GetEquipmentHistoryAsync(n.Value,ct)).Select(BorrowDto));});
    }

    public static void MapBorrowingApi(this WebApplication app)
    {
        var g=app.MapGroup("/api/v1/borrowings");
        g.MapGet("",async(string? search,string? status,string? sort,string? direction,BorrowingQueryService query,CancellationToken ct)=>{if(status is not null&&!Enum.TryParse<BorrowingStatusFilter>(status,true,out _))return Error(400,"invalid_query","status must be Active, Returned, or All.");if(sort is not null&&sort is not ("borrowedDate" or "expectedReturnDate"))return Error(400,"invalid_query","sort must be borrowedDate or expectedReturnDate.");if(direction is not null&&direction is not ("asc" or "desc"))return Error(400,"invalid_query","direction must be asc or desc.");var rows=await query.SearchAsync(new BorrowingSearchCriteria{SearchText=search,Status=Enum.TryParse<BorrowingStatusFilter>(status,true,out var st)?st:BorrowingStatusFilter.All,SortBy=sort=="expectedReturnDate"?BorrowingSortField.ExpectedReturnDate:BorrowingSortField.CheckoutDate,Descending=direction=="desc"},ct);return Results.Ok(rows.Select(BorrowDto));});
        g.MapGet("/{id}",async(string id,BorrowingQueryService query,CancellationToken ct)=>{if(!int.TryParse(id,out var n)||n<1)return Error(404,"not_found","Borrowing was not found.");var rows=await query.SearchAsync(new BorrowingSearchCriteria(),ct);var row=rows.FirstOrDefault(b=>b.BorrowingId==n);return row is null?Error(404,"not_found","Borrowing was not found."):Results.Ok(BorrowDto(row));});
        g.MapPost("",async(BorrowInput x,BorrowEquipmentService service,BorrowingQueryService query,CancellationToken ct)=>{var s=ParseId(x.StudentId);var e=ParseId(x.EquipmentId);if(s is null||e is null||!DateOnly.TryParse(x.ExpectedReturnDate,out var due))return Error(400,"invalid_request","Student, equipment, and a valid expectedReturnDate are required.");var r=await service.BorrowEquipmentAsync(0,s.Value,e.Value,due.ToDateTime(TimeOnly.MinValue),ct);if(!r.Succeeded)return BorrowFailure(r.FailureReason);var rows=await query.SearchAsync(new BorrowingSearchCriteria{Status=BorrowingStatusFilter.Active},ct);var row=rows.Where(b=>b.StudentId==s.Value&&b.EquipmentId==e.Value).OrderByDescending(b=>b.BorrowingId).FirstOrDefault();return row is null?Error(500,"server_error","The borrowing could not be read after creation."):Results.Created($"/api/v1/borrowings/{Key(row.BorrowingId)}",BorrowDto(row));});
        app.MapPost("/api/v1/checkout-requests",async(MultiBorrowInput x,CheckoutMultipleEquipmentService service,BorrowingQueryService query,CancellationToken ct)=>{var s=ParseId(x.StudentId);if(s is null||!DateOnly.TryParse(x.ExpectedReturnDate,out var due)||x.EquipmentIds is null||x.EquipmentIds.Any(id=>ParseId(id) is null))return Error(400,"invalid_request","Student, equipment IDs, and a valid expectedReturnDate are required.");var ids=x.EquipmentIds.Select(id=>ParseId(id)!.Value).ToArray();var result=await service.CheckOutAsync(s.Value,ids,due.ToDateTime(TimeOnly.MinValue),ct);if(!result.Succeeded)return BorrowFailure(result.FailureReason);var rows=await query.SearchAsync(new BorrowingSearchCriteria{Status=BorrowingStatusFilter.Active},ct);return Results.Created("/api/v1/borrowings",new{borrowings=rows.Where(b=>b.StudentId==s.Value&&ids.Contains(b.EquipmentId)).Select(BorrowDto)});});
        g.MapPost("/{id}/return",async(string id,ReturnEquipmentService service,BorrowingQueryService query,CancellationToken ct)=>{if(!int.TryParse(id,out var n)||n<1)return Error(404,"not_found","Borrowing was not found.");var result=await service.ReturnEquipmentAsync(n,ct);if(!result.Succeeded)return result.FailureReason switch{ReturnFailureReason.BorrowingNotFound=>Error(404,"not_found","Borrowing was not found."),ReturnFailureReason.PersistenceFailed=>Error(500,"server_error","The return could not be saved."),ReturnFailureReason.OutcomeUnknown=>Error(500,"outcome_unknown","The result is unknown. Refresh before retrying."),_=>Error(409,"conflict","This borrowing has already been returned or changed.")};var rows=await query.SearchAsync(new BorrowingSearchCriteria());var row=rows.FirstOrDefault(b=>b.BorrowingId==n);return row is null?Error(404,"not_found","Borrowing was not found."):Results.Ok(BorrowDto(row));});
    }

    private static IResult BorrowFailure(BorrowFailureReason reason)=>reason switch{BorrowFailureReason.StudentNotFound or BorrowFailureReason.EquipmentNotFound=>Error(404,"not_found","Student or equipment was not found."),BorrowFailureReason.InvalidReturnDate=>Error(400,"invalid_date","Expected return date must be later than today."),BorrowFailureReason.PersistenceFailed=>Error(500,"server_error","The operation could not be saved."),BorrowFailureReason.OutcomeUnknown=>Error(500,"outcome_unknown","The result is unknown. Refresh before retrying."),BorrowFailureReason.Conflict=>Error(409,"conflict","The record changed; refresh and retry."),_=>Error(409,"business_rule",reason.ToString())};
}

internal sealed record StudentInput(string StudentNumber,string FullName,string? Contact);
internal sealed record EligibilityInput(bool IsEligible);
internal sealed record EquipmentInput(string EquipmentCode,string Name,string? Description);
internal sealed record BorrowInput(string StudentId,string EquipmentId,string ExpectedReturnDate);
internal sealed record MultiBorrowInput(string StudentId,string[] EquipmentIds,string ExpectedReturnDate);
